// Reel « Collaborer avant de s'associer » — Higgsedit v0.14 (f39e3bc5882b), 1080x1920 @ 30 fps.
// Generated by gen_edit.py: every time below is on the jump-cut timeline of media/cut.mp4.
import { createRequire } from "node:module";

const D = /*__DATA__*/null;
const { PAL } = D;
const W = 1080, H = 1920;
const FONT = "Montserrat";

// Measure with the same Montserrat 700 face the renderer ships, so rows and cards size exactly.
const require = createRequire("/opt/fable/package.json");
const { GlobalFonts, createCanvas } = require("@napi-rs/canvas");
GlobalFonts.registerFromPath("/opt/fable/fonts-kit/montserrat-700.woff2", "MeasureMont");
const ctx = createCanvas(4, 4).getContext("2d");
const tw = (s, size) => { ctx.font = `700 ${size}px MeasureMont`; return Math.ceil(ctx.measureText(s).width * 1.06) + 10; };

const SHADOW = { x: 0, y: 6, blur: 22, color: "#000000A0" };
const EASE = [0.2, 0.8, 0.2, 1];                                   // Module C4: the only curve used in this reel
const MOCKUP_SPRING = { kind: "spring", stiffness: 300, damping: 24 }; // mockup entries only
const ez = (e) => (e === "hold" || e === "linear" ? e : EASE);
const MEDIA = "/home/user/w";
const col = (k) => PAL[k] || k;
// Film grain (≤ 0.04) + soft vignette, applied to the footage only.
const GRAIN = `vec4 pixel(vec2 uv){
  vec4 c = texture(u_src, uv);
  float n = fract(sin(dot(floor(uv * u_resolution) + floor(u_time * 30.0) * 17.0, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  vec2 d = (uv - 0.5) * vec2(1.0, 0.82);
  float v = 1.0 - u_vig * smoothstep(0.30, 0.78, length(d) * 1.35);
  return vec4(clamp((c.rgb + n * u_amt) * v, 0.0, 1.0) * c.a, c.a);
}`;
// Stroke "draw": the mask is centred on the stroke origin and grows to twice the path length,
// so the visible part advances from the origin in the drawing direction.
const drawX = (w, h, at, dur) => ({
  mask: { shape: "rectangle", x: -1, y: -4, width: 2, height: h + 8 },
  draw: { property: "maskWidth", keyframes: [{ at: 0, value: 2, easing: "hold" }, { at: Math.max(at, 0.001), value: 2, easing: EASE }, { at: at + dur, value: 2 * w + 4 }] },
});
const fadeKeys = (inAt, inDur, outAt, outDur) => {
  const k = [];
  if (inAt > 0) k.push({ at: 0, value: 0, easing: "hold" });
  k.push({ at: inAt, value: inAt === 0 && inDur === 0 ? 1 : 0 }, { at: inAt + inDur, value: 1 });
  k.push({ at: outAt, value: 1 }, { at: outAt + outDur - 0.002, value: 0 });
  return [{ property: "opacity", keyframes: k.filter((x, i, a) => i === 0 || x.at > a[i - 1].at) }];
};
const roundRect = (w, h, r, i = 2) =>
  `M ${r + i} ${i} L ${w - r - i} ${i} Q ${w - i} ${i} ${w - i} ${r + i} L ${w - i} ${h - r - i} Q ${w - i} ${h - i} ${w - r - i} ${h - i} L ${r + i} ${h - i} Q ${i} ${h - i} ${i} ${h - r - i} L ${i} ${r + i} Q ${i} ${i} ${r + i} ${i} Z`;

export default async ({ project, text, rect, media, path, frame, icon }) => {
  const p = await project({ dir: "reel", size: `${W}x${H}`, fps: 30, background: PAL.bg });
  const v = await p.add(`${MEDIA}/cut.mp4`);
  const brolls = await Promise.all(D.broll.map((b) => p.add(`${MEDIA}/broll/${b.file}`)));
  const checklistMov = await p.add(`${MEDIA}/checklist.mov`);

  // ---- spine: picture + cleaned voice (audio lives here) ----
  p.cut(v, { from: 0, dur: D.DUR, fit: "cover" });

  // ---- footage chunks (punch-ins, zoom-whips with motion blur, micro drift, grain) and Module B B-roll
  //      cutaways, composed in time order: Higgsedit fills a track from its last placed clip onwards ----
  const segs = [...D.chunks.map((c) => ({ kind: "footage", a: c.a, c })), ...D.broll.map((b, i) => ({ kind: "broll", a: b.at, b, i }))]
    .sort((x, y) => x.a - y.a);
  for (const sg of segs) {
    if (sg.kind === "broll") {
      // 8-frame dissolve in, push-in 100 -> 104 %, hard cut back to the face
      const b = sg.b, len = b.end - b.at;
      p.compose(media({ file: brolls[sg.i], x: 0, y: 0, width: W, height: H, fit: "cover", trimStart: 0,
        effects: [{ kind: "shader", params: { glsl: GRAIN, amt: 0.03, vig: 0.14 } }],
        animate: [{ property: "opacity", keyframes: [{ at: 0, value: 0, easing: EASE }, { at: 8 / 30, value: 1 }] },
          { property: "scale", from: 1, to: 1.04, duration: len - 0.001, easing: "linear" }] }),
        { at: b.at, dur: len, name: `broll ${b.file}` });
      continue;
    }
    const c = sg.c, len = c.b - c.a;
    const drift = [];
    for (let t = 0; t < len; t += 2.5) drift.push({ at: t, value: +(5 * Math.sin((c.a + t) / 2.2)).toFixed(2) });
    drift.push({ at: len - 0.001, value: +(5 * Math.sin(c.b / 2.2)).toFixed(2) });
    p.compose(media({
      file: v, x: 0, y: 0, width: W, height: H, fit: "cover", trimStart: c.a,
      effects: [{ kind: "shader", params: { glsl: GRAIN, amt: 0.03, vig: 0.14 } }],
      ...(c.blur ? { motionBlur: { samples: 8, shutter: 0.7 } } : {}),
      animate: [
        { property: "scale", keyframes: c.k.map((k) => ({ ...k, easing: ez(k.easing), value: +(k.value * 1.012).toFixed(4) })) },
        { property: "offsetY", keyframes: drift.filter((x, i, a) => i === 0 || x.at > a[i - 1].at + 0.01), easing: EASE },
      ],
    }), { at: c.a, dur: len, name: `footage ${c.a.toFixed(2)}` });
  }

  // ---- bottom scrim so white captions stay legible over the white blazer ----
  p.compose(rect({ x: 0, y: 1180, width: W, height: 740,
    fill: { kind: "linear", angle: 180, stops: [{ offset: 0, color: "#000000", opacity: 0 }, { offset: 0.45, color: "#000000", opacity: 0.38 }, { offset: 1, color: "#000000", opacity: 0.55 }] } }),
    { at: 0, dur: D.DUR, name: "scrim" });

  // ---- Module C: kinetic-type hook (0–3.6 s) over the full-frame talking head, chest band, face untouched ----
  {
    const K = D.hook, words = K.words, CY = 1150;
    const nodes = [rect({ x: 0, y: 900, width: W, height: 520,
      fill: { kind: "linear", angle: 180, stops: [{ offset: 0, color: "#000000", opacity: 0 }, { offset: 0.5, color: "#000000", opacity: 0.45 }, { offset: 1, color: "#000000", opacity: 0 }] } })];
    words.forEach(([w, at, c], i) => {
      const next = i + 1 < words.length ? words[i + 1][1] : K.end;
      const size = Math.min(150, Math.floor(150 * 880 / tw(w, 150)));
      const ww = tw(w, size), hh = Math.round(size * 1.3);
      nodes.push(frame({ x: (W - ww) / 2, y: CY - hh / 2, width: ww, height: hh, origin: "center", layout: "none", at, duration: next - at,
        motion: { enter: { from: { scale: 1.18, opacity: 0 }, duration: 0.2, easing: EASE } } },
        [text(w, { x: 0, y: 0, width: ww, height: hh, align: "center", fontFamily: FONT, fontWeight: 700, fontSize: size, color: col(c),
          shadow: { x: 0, y: 8, blur: 30, color: "#000000C0" },
          animate: [{ property: "blur", keyframes: [{ at: 0, value: 14, easing: EASE }, { at: 0.2, value: 0 }] }] })]));
    });
    p.compose(nodes, { at: 0, dur: K.end, name: "kinetic hook" });
  }

  // ---- karaoke captions: 3–5 words, active word in accent ----
  for (const c of D.caps) {
    const words = c.w.map((w) => {
      const keys = [];
      if (w.on > 0) keys.push({ at: 0, value: PAL.fg, easing: "hold" });
      keys.push({ at: w.on, value: PAL.accent, easing: "hold" });
      if (w.off < c.dur - 0.02) keys.push({ at: w.off, value: PAL.fg, easing: "hold" });
      if (keys.length < 2) keys.push({ at: c.dur - 0.01, value: keys[keys.length - 1].value });
      return text(w.t, { width: tw(w.t, 68), height: 84, align: "center", fontFamily: FONT, fontWeight: 700, fontSize: 68, color: PAL.fg,
        shadow: { x: 0, y: 4, blur: 18, color: "#000000B0" }, animate: [{ property: "color", keyframes: keys }] });
    });
    p.compose(frame({ x: 80, y: 1395, width: 920, height: 176, layout: "row", wrap: true, gap: 6, rowGap: 2, justify: "center", align: "start",
      motion: { enter: { from: { opacity: 0, y: 10 }, duration: 0.1 } } }, words), { at: c.at, dur: c.dur, name: "caption" });
  }

  // ---- keyword cards (pop in spring 0.35 s, out 0.25 s) ----
  for (const c of D.cards) {
    const size = 50, parts = c.parts.map(([s, k]) => [s.trim(), col(k)]);
    const iw = c.icon ? 60 : 0, gap = 8;
    const inner = iw + (c.icon ? gap : 0) + parts.reduce((a, [s]) => a + tw(s, size), 0) + gap * (parts.length - 1);
    const cw = Math.min(W - 80, inner + 76);
    p.compose(frame({ x: (W - cw) / 2, y: 1060, width: cw, height: 124, origin: "center", layout: "row", gap, align: "center", justify: "center",
      background: "#0F0F12E8", radius: 30, shadow: SHADOW,
      motion: { enter: { from: { scale: 0.6, opacity: 0 }, duration: 0.35, easing: EASE }, exit: { to: { scale: 0.92, opacity: 0 }, duration: 0.25, easing: EASE } } },
      [...(c.icon ? [icon(c.icon, { size: iw, color: PAL.accent, strokeWidth: 2 })] : []),
        ...parts.map(([s, k]) => text(s, { width: tw(s, size), height: 64, align: "center", fontFamily: FONT, fontWeight: 700, fontSize: size, color: k }))]),
      { at: c.at, dur: c.dur, name: "card" });
  }

  // ---- schema 1: rising curve crossing the "manageable" line ----
  {
    const s = D.curve, dur = s.end - s.at, X = 150, Y = 960, PW = 780, PH = 400;
    const cw = 660, ch = 300, d1 = drawX(cw, ch, 0.35, 1.1);
    const out = dur - 0.3;
    p.compose([
      rect({ x: X, y: Y, width: PW, height: PH, radius: 32, fill: "#0F0F12", opacity: 0.78, shadow: SHADOW, animate: [{ property: "opacity", keyframes: [{ at: 0, value: 0 }, { at: 0.2, value: 0.78 }, { at: out, value: 0.78 }, { at: dur - 0.001, value: 0 }] }] }),
      path({ x: X + 50, y: Y + 250, width: 680, height: 8, d: "M 2 4 L 678 4", stroke: { width: 3, color: "#FFFFFF", cap: "round" }, dash: [14, 12], animate: fadeKeys(0.1, 0.25, out, 0.3).map((a) => ({ ...a, keyframes: a.keyframes.map((k) => ({ ...k, value: k.value * 0.7 })) })) }),
      text("ce que vous gérez", { x: X + 54, y: Y + 262, width: 360, height: 44, fontFamily: FONT, fontWeight: 700, fontSize: 30, color: "#FFFFFFB3", animate: fadeKeys(0.1, 0.25, out, 0.3) }),
      path({ x: X + 60, y: Y + 50, width: cw, height: ch, d: "M 4 290 C 180 285 300 250 380 170 C 460 90 560 40 652 10", stroke: { width: 4, color: PAL.accent, cap: "round" },
        mask: d1.mask, shadow: { x: 0, y: 4, blur: 12, color: "#00000099" }, animate: [d1.draw, ...fadeKeys(0, 0, out, 0.3)] }),
      path({ x: X + 60 + 626, y: Y + 50 - 8, width: 40, height: 40, d: "M 6 8 L 32 12 L 22 36", stroke: { width: 4, color: PAL.accent, cap: "round" }, animate: fadeKeys(1.4, 0.12, out, 0.3) }),
    ], { at: s.at, dur, name: "schema curve" });
  }

  // ---- Module C: checklist mockup (HTML -> ProRes 4444 alpha), spring entry, 2.5D micro-parallax ----
  {
    const s = D.checklist, dur = s.end - s.at, MW = 960, MH = 580;
    p.compose(frame({ x: (W - MW) / 2, y: 830, width: MW, height: MH, origin: "center", layout: "none",
      motion: { enter: { from: { scale: 0.85, y: 40 }, duration: 0.4, easing: MOCKUP_SPRING },
                exit: { to: { scale: 0.96, opacity: 0 }, duration: 0.25, easing: EASE } } },
      [media({ file: checklistMov, x: 0, y: 0, width: MW, height: MH, fit: "fill", trimStart: 0,
        animate: [{ property: "opacity", keyframes: [{ at: 0, value: 0, easing: EASE }, { at: 0.15, value: 1 }] },
          { property: "offsetX", keyframes: [{ at: 0, value: -2, easing: EASE }, { at: dur / 2, value: 2, easing: EASE }, { at: dur - 0.01, value: -2 }] },
          { property: "offsetY", keyframes: [{ at: 0, value: 2, easing: EASE }, { at: dur / 2, value: -2, easing: EASE }, { at: dur - 0.01, value: 2 }] }] })]),
      { at: s.at, dur, name: "mockup checklist" });
  }

  // ---- CTA 2 s + fade out ----
  {
    const t1 = "Abonne-toi pour la suite", t2 = "Collaborer d'abord. S'associer ensuite.";
    p.compose([
      rect({ x: 0, y: 0, width: W, height: H, fill: PAL.bg, animate: [{ property: "opacity", from: 0, to: 1, duration: 0.25 }] }),
      frame({ x: (W - 132) / 2, y: 700, width: 132, height: 132, origin: "center", layout: "row", align: "center", justify: "center", background: "#F2B5441F", radius: 66,
        motion: { enter: { from: { scale: 0 }, duration: 0.4, easing: MOCKUP_SPRING } } },
        [icon("bell", { size: 72, color: PAL.accent, strokeWidth: 2 })]),
      text(t1, { x: (W - tw(t1, 64)) / 2, y: 880, width: tw(t1, 64), height: 80, fontFamily: FONT, fontWeight: 700, fontSize: 64, color: PAL.fg, shadow: SHADOW,
        motion: { by: "word", from: { opacity: 0, y: 18 }, at: 0.15, duration: 0.45, overlap: 0.5, easing: "ease-out" } }),
      text(t2, { x: (W - tw(t2, 38)) / 2, y: 990, width: tw(t2, 38), height: 50, fontFamily: FONT, fontWeight: 700, fontSize: 38, color: "#FFFFFFB3",
        animate: [{ property: "opacity", keyframes: [{ at: 0, value: 0, easing: "hold" }, { at: 0.5, value: 0 }, { at: 0.8, value: 1 }] }] }),
      rect({ x: 0, y: 0, width: W, height: H, fill: "#000000", animate: [{ property: "opacity", keyframes: [{ at: 0, value: 0, easing: "hold" }, { at: D.CTA - 0.4, value: 0 }, { at: D.CTA - 0.001, value: 1 }] }] }),
    ], { at: D.DUR, dur: D.CTA, name: "cta" });
  }

  const mode = process.env.REEL_MODE || "frames";
  if (mode === "frames") {
    for (const t of D.busy) await p.frame(t, `renders/busy_${t.toFixed(2)}.png`);
  } else if (mode === "draft") {
    await p.render("renders/draft.mp4", { draft: true });
  } else if (mode === "master") {
    await p.render("renders/master.mp4", { depth: 8, bitrate: 10_000_000, concurrency: 3 });
  }
};
